    #[arg(long, default_value = "1")]
    min_repetitions: usize,

    /// Specifies the minimum length a repeated substring must have in order to be converted if --repetitions is set
    #[arg(long, default_value = "1")]
    min_substring_length: usize,

    /// Removes the caret anchor `^` from the resulting regular expression
    #[arg(long)]
    no_start_anchor: bool,

    /// Removes the dollar sign anchor `$` from the resulting regular expression
    #[arg(long)]
    no_end_anchor: bool,

    /// Removes the caret and dollar sign anchors from the resulting regular expression
    #[arg(long)]
    no_anchors: bool,

    /// Produces a nicer-looking regular expression in verbose mode
    #[arg(short, long)]
    verbose: bool,

    /// Provides syntax highlighting for the resulting regular expression
    #[arg(short, long)]
    colorize: bool,

    /// Performs case-insensitive matching, letters match both upper and lower case
    #[arg(short, long)]
    ignore_case: bool,

    /// Replaces non-capturing groups with capturing ones
    #[arg(short, long)]
    capture_groups: bool,
}

fn main() {
    let args = Args::parse();

    let test_cases = if let Some(file) = args.file {
        read_from_file(&file)
    } else if args.input.is_empty() {
        eprintln!("Error: No input provided");
        std::process::exit(1);
    } else if args.input.len() == 1 && args.input[0] == "-" {
        read_from_stdin()
    } else {
        args.input
    };

    if test_cases.is_empty() {
        eprintln!("Error: No test cases provided");
        std::process::exit(1);
    }

    let regex = generate_regex(&test_cases, &args);
    println!("{}", regex);
