fn read_from_file(path: &str) -> Vec<String> {
    if path == "-" {
        let stdin = io::stdin();
        let line = stdin.lock().lines().next();
        if let Some(Ok(line)) = line {
            read_from_file(&line)
        } else {
            Vec::new()
        }
    } else {
        match fs::read_to_string(path) {
            Ok(contents) => {
                contents
                    .lines()
                    .map(|s| s.to_string())
                    .collect()
            }
            Err(e) => {
                eprintln!("Error reading file: {}", e);
                std::process::exit(1);
            }
        }
    }
}

fn read_from_stdin() -> Vec<String> {
    let stdin = io::stdin();
    stdin
        .lock()
        .lines()
        .filter_map(|line| line.ok())
        .collect()
}

fn generate_regex(test_cases: &[String], args: &Args) -> String {
    // For a start, just generate a basic regex that matches any of the test cases
    let mut regex = String::new();

    if args.ignore_case {
        regex.push_str("(?i)");
    }

    if !args.no_anchors && !args.no_start_anchor {
        regex.push('^');
    }

    // Generate the main pattern
    let pattern = generate_pattern(test_cases, args);
    regex.push_str(&pattern);

    if !args.no_anchors && !args.no_end_anchor {
        regex.push('$');
    }

    if args.verbose {
        format_verbose(&regex)
    } else if args.colorize {
        colorize(&regex)
    } else {
        regex
    }
}

fn generate_pattern(test_cases: &[String], args: &Args) -> String {
    // If all test cases are the same, return that test case
    if test_cases.iter().all(|s| s == &test_cases[0]) {
        return escape_pattern(&test_cases[0], args);
    }

    // If there's only one test case, return it
    if test_cases.len() == 1 {
        return escape_pattern(&test_cases[0], args);
    }

    // Try to find common patterns
    if let Some(pattern) = find_character_class(test_cases, args) {
        return pattern;
    }

    if let Some(pattern) = find_common_prefix_suffix(test_cases, args) {
        return pattern;
    }

    // Default: alternation
    let alternatives: Vec<String> = test_cases
        .iter()
        .map(|s| escape_pattern(s, args))
        .collect();

    let group_start = if args.capture_groups { "(" } else { "(?:" };
    format!("{}{})", group_start, alternatives.join("|"))
}

fn escape_pattern(s: &str, args: &Args) -> String {
    let mut result = String::new();

    for ch in s.chars() {
        if args.escape && !ch.is_ascii() {
            // Escape non-ASCII characters
            if args.with_surrogates && ch as u32 > 0xFFFF {
                // Convert to surrogate pair
                let code_point = ch as u32;
                let high = ((code_point - 0x10000) >> 10) + 0xD800;
                let low = ((code_point - 0x10000) & 0x3FF) + 0xDC00;
                result.push_str(&format!("\\u{{{:x}}}\\u{{{:x}}}", high, low));
            } else {
                result.push_str(&format!("\\u{{{:x}}}", ch as u32));
            }
        } else if needs_escaping(ch) {
            result.push('\\');
            result.push(ch);
        } else {
            result.push(ch);
        }
    }

    result
}

fn needs_escaping(ch: char) -> bool {
    matches!(ch, '.' | '*' | '+' | '?' | '(' | ')' | '[' | ']' | '{' | '}' | '|' | '\\' | '^' | '$')
}

fn find_character_class(test_cases: &[String], args: &Args) -> Option<String> {
    // If all test cases have the same length
    let first_len = test_cases[0].len();
    if test_cases.iter().all(|s| s.len() == first_len) && first_len == 1 {
        // Single characters - can create character class
        let chars: BTreeSet<String> = test_cases.iter().cloned().collect();
        if chars.len() == test_cases.len() {
            let mut char_list: Vec<char> = chars.iter().flat_map(|s| s.chars()).collect();
            char_list.sort();

            // Check if we can use a range
            if can_use_range(&char_list) {
                if char_list.len() == 1 {
                    return Some(escape_pattern(&char_list[0].to_string(), args));
                }
                return Some(format!("[{}-{}]", char_list[0], char_list[char_list.len() - 1]));
            }

            if char_list.len() == 1 {
                return Some(escape_pattern(&char_list[0].to_string(), args));
            }
        }
    }

    None
}

fn can_use_range(chars: &[char]) -> bool {
    if chars.len() < 2 {
        return false;
    }

    for i in 1..chars.len() {
        if (chars[i] as u32) != (chars[i - 1] as u32) + 1 {
            return false;
        }
    }

    true
}

fn find_common_prefix_suffix(test_cases: &[String], args: &Args) -> Option<String> {
    // Find common prefix
    let prefix = find_common_prefix(test_cases);
    let suffix = find_common_suffix(test_cases);

    if !prefix.is_empty() || !suffix.is_empty() {
        let mut parts = Vec::new();

        if !prefix.is_empty() {
            parts.push(escape_pattern(&prefix, args));
        }

        let remaining: Vec<String> = test_cases
            .iter()
            .map(|s| {
                let s = if !prefix.is_empty() {
                    &s[prefix.len()..]
                } else {
                    s
                };
                if !suffix.is_empty() {
                    &s[..s.len() - suffix.len()]
                } else {
                    s
                }
            })
            .map(|s| s.to_string())
            .collect();

        if remaining.iter().all(|s| s.is_empty()) {
            // All remaining parts are empty
            let mut result = parts.join("");
            if !suffix.is_empty() {
                result.push_str(&escape_pattern(&suffix, args));
            }
            return Some(result);
        }

        let middle = generate_pattern(&remaining, args);
        parts.push(middle);

        if !suffix.is_empty() {
            parts.push(escape_pattern(&suffix, args));
        }

        return Some(parts.join(""));
    }

    None
}

fn find_common_prefix(test_cases: &[String]) -> String {
    if test_cases.is_empty() {
        return String::new();
    }

    let mut prefix = String::new();
    let first = &test_cases[0];

    for (i, ch) in first.chars().enumerate() {
        if test_cases.iter().all(|s| {
            s.chars().nth(i).map_or(false, |c| c == ch)
        }) {
            prefix.push(ch);
        } else {
            break;
        }
    }

    prefix
}

fn find_common_suffix(test_cases: &[String]) -> String {
    if test_cases.is_empty() {
        return String::new();
    }

    let first = &test_cases[0];
    let mut suffix = String::new();

    for (i, ch) in first.chars().rev().enumerate() {
        if test_cases.iter().all(|s| {
            s.chars().rev().nth(i).map_or(false, |c| c == ch)
        }) {
            suffix.insert(0, ch);
        } else {
            break;
        }
    }

    suffix
}

