    let mut result = String::from("(?x)\n");
    let mut depth = 0;
    let mut in_escape = false;

    for ch in regex.chars() {
        if in_escape {
            result.push(ch);
            in_escape = false;
        } else if ch == '\\' {
            result.push(ch);
            in_escape = true;
        } else if ch == '(' {
            result.push(ch);
            depth += 1;
            result.push('\n');
            for _ in 0..depth {
                result.push_str("  ");
            }
        } else if ch == ')' {
            depth = depth.saturating_sub(1);
            result.push('\n');
            for _ in 0..depth {
                result.push_str("  ");
            }
            result.push(ch);
        } else if ch == '|' {
            result.push(ch);
            result.push('\n');
            for _ in 0..depth {
                result.push_str("  ");
            }
        } else if ch == '^' || ch == '$' {
            if !result.ends_with('\n') && !result.ends_with(' ') {
                result.push('\n');
                for _ in 0..depth {
                    result.push_str("  ");
                }
            }
            result.push(ch);
            if ch == '^' {
                result.push('\n');
                for _ in 0..depth {
                    result.push_str("  ");
                }
            }
        } else {
            result.push(ch);
        }
    }

    result.push('\n');
    result
}

fn colorize(regex: &str) -> String {
    let mut result = String::new();
    let mut in_escape = false;

    for (i, ch) in regex.chars().enumerate() {
        if in_escape {
            result.push(ch);
            in_escape = false;
        } else if ch == '\\' {
            result.push(ch);
            in_escape = true;
        } else if ch == '^' || ch == '$' {
            result.push_str("\x1b[1;33m");
            result.push(ch);
            result.push_str("\x1b[0m");
        } else if ch == '(' || ch == ')' || matches!(ch, '?' | ':' | '|') && i > 0 {
            if ch == '|' {
                result.push_str("\x1b[1;31m");
            } else {
                result.push_str("\x1b[1;32m");
            }
            result.push(ch);
            result.push_str("\x1b[0m");
        } else {
            result.push(ch);
        }
    }

    result
}
