        let s2 = &test_cases[1];

        if s1.len() + 1 == s2.len() && s2.starts_with(s1) {
            let extra = &s2[s1.len()..];
            if extra.len() == 1 {
                return Some(format!("{}{}?", escape_pattern(s1, args), escape_pattern(extra, args)));
            }
        }

        if s2.len() + 1 == s1.len() && s1.starts_with(s2) {
            let extra = &s1[s2.len()..];
            if extra.len() == 1 {
                return Some(format!("{}{}?", escape_pattern(s2, args), escape_pattern(extra, args)));
            }
        }
    }

    None
}

fn find_common_prefix(test_cases: &[String]) -> String {
    if test_cases.is_empty() {
        return String::new();
    }

    let first = &test_cases[0];
    let mut prefix = String::new();

    for (i, ch) in first.chars().enumerate() {
        if test_cases.iter().all(|s| {
            s.chars().nth(i).map_or(false, |c| c == ch)
        }) {
            prefix.push(ch);
        } else {
            break;
        }
    }

    prefix
}

fn find_common_suffix(test_cases: &[String]) -> String {
    if test_cases.is_empty() {
        return String::new();
    }

    let first = &test_cases[0];
    let mut suffix = String::new();

    for (i, ch) in first.chars().rev().enumerate() {
        if test_cases.iter().all(|s| {
            s.chars().rev().nth(i).map_or(false, |c| c == ch)
        }) {
            suffix.insert(0, ch);
        } else {
            break;
        }
    }

    suffix
}

fn format_verbose(regex: &str) -> String {
    let mut result = String::from("(?x)\n");
    let mut depth = 0;
    let mut in_escape = false;

    for ch in regex.chars() {
        if in_escape {
            result.push(ch);
            in_escape = false;
        } else if ch == '\\' {
            result.push(ch);
            in_escape = true;
        } else if ch == '(' {
            result.push(ch);
            depth += 1;
            result.push('\n');
            for _ in 0..depth {
                result.push_str("  ");
            }
        } else if ch == ')' {
            depth = depth.saturating_sub(1);
            result.push('\n');
            for _ in 0..depth {
                result.push_str("  ");
            }
            result.push(ch);
        } else if ch == '|' {
            result.push(ch);
            result.push('\n');
            for _ in 0..depth {
                result.push_str("  ");
            }
        } else if ch == '^' || ch == '$' {
            if !result.ends_with('\n') && !result.ends_with(' ') {
                result.push('\n');
                for _ in 0..depth {
                    result.push_str("  ");
                }
            }
            result.push(ch);
            result.push('\n');
            for _ in 0..depth {
                result.push_str("  ");
            }
        } else {
            result.push(ch);
        }
    }

    result.push('\n');
    result
}

fn colorize(regex: &str) -> String {
    let mut result = String::new();
    let mut in_escape = false;
    let mut chars = regex.chars().enumerate().peekable();

    while let Some((i, ch)) = chars.next() {
        if in_escape {
            result.push(ch);
            in_escape = false;
        } else if ch == '\\' {
            result.push(ch);
            in_escape = true;
        } else if ch == '^' || ch == '$' {
            result.push_str("\x1b[1;33m");
            result.push(ch);
            result.push_str("\x1b[0m");
        } else if ch == '(' || ch == ')' {
            result.push_str("\x1b[1;32m");
            result.push(ch);
            result.push_str("\x1b[0m");
        } else if ch == '|' {
            result.push_str("\x1b[1;31m");
            result.push(ch);
            result.push_str("\x1b[0m");
        } else if ch == '?' || ch == ':' {
            result.push_str("\x1b[1;32m");
            result.push(ch);
            result.push_str("\x1b[0m");
        } else {
            result.push(ch);
        }
    }

    result
}
