            read_from_file(&line)
        } else {
            Vec::new()
        }
    } else {
        match fs::read_to_string(path) {
            Ok(contents) => {
                contents
                    .lines()
                    .map(|s| s.to_string())
                    .collect()
            }
            Err(e) => {
