        if test_cases.iter().all(|s| {
            s.chars().rev().nth(i).map_or(false, |c| c == ch)
        }) {
            suffix.insert(0, ch);
        } else {
            break;
        }
    }

    suffix
}

fn format_verbose(regex: &str) -> String {
    let mut result = String::from("(?x)\n");
    let mut depth: i32 = 0;
    let mut in_escape = false;

    for ch in regex.chars() {
        if in_escape {
            result.push(ch);
            in_escape = false;
        } else if ch == '\\' {
            result.push(ch);
            in_escape = true;
        } else if ch == '(' {
            result.push(ch);
            depth += 1;
            result.push('\n');
            for _ in 0..depth {
                result.push_str("  ");
            }
        } else if ch == ')' {
            depth -= 1;
            result.push('\n');
            for _ in 0..depth {
                result.push_str("  ");
            }
            result.push(ch);
        } else if ch == '|' {
            result.push(ch);
            result.push('\n');
            for _ in 0..depth {
                result.push_str("  ");
            }
        } else if ch == '^' || ch == '$' {
            if !result.ends_with('\n') && !result.ends_with(' ') {
                result.push('\n');
                for _ in 0..depth {
                    result.push_str("  ");
                }
            }
            result.push(ch);
            result.push('\n');
            for _ in 0..depth {
                result.push_str("  ");
            }
        } else {
            result.push(ch);
        }
    }

    result.push('\n');
    result
}

fn colorize(regex: &str) -> String {
    let mut result = String::new();
    let mut in_escape = false;

    for ch in regex.chars() {
        if in_escape {
