            result.push_str("\x1b[0m");
        } else if ch == '?' || ch == ':' {
            result.push_str("\x1b[1;32m");
            result.push(ch);
            result.push_str("\x1b[0m");
        } else {
            result.push(ch);
        }
    }

    result
