                std::process::exit(1);
            }
            _ => {
                input_strings.push(args[i].clone());
            }
        }
        i += 1;
    }

    if input_strings.is_empty() {
        eprintln!("Error: No test cases provided");
        std::process::exit(1);
    }

    let regex = generate_regex(&input_strings, &parsed_args);
    println!("{}", regex);
}

