                }
            }
            result.push(ch);
            if ch == '^' {
                result.push('\n');
                for _ in 0..depth {
                    result.push_str("  ");
                }
            }
        } else {
            result.push(ch);
        }
    }

    result.push('\n');
    result
}

fn colorize(regex: &str) -> String {
    let mut result = String::new();
    let mut in_escape = false;
    let mut chars_iter = regex.chars().peekable();

    while let Some(ch) = chars_iter.next() {
        if in_escape {
            result.push(ch);
            in_escape = false;
        } else if ch == '\\' {
            result.push(ch);
            in_escape = true;
        } else if ch == '^' || ch == '$' {
            result.push_str("\x1b[1;33m");
            result.push(ch);
            result.push_str("\x1b[0m");
        } else if ch == '(' {
            result.push_str("\x1b[1;32m");
            result.push(ch);
            // Check for ?:
            if let Some(&next) = chars_iter.peek() {
                if next == '?' {
                    chars_iter.next();
                    result.push('?');
                    if let Some(&colon) = chars_iter.peek() {
                        if colon == ':' {
                            chars_iter.next();
                            result.push(':');
                        }
                    }
                }
            }
            result.push_str("\x1b[0m");
        } else if ch == ')' {
            result.push_str("\x1b[1;32m");
            result.push(ch);
            result.push_str("\x1b[0m");
        } else if ch == '|' {
            result.push_str("\x1b[1;31m");
            result.push(ch);
            result.push_str("\x1b[0m");
        } else {
            result.push(ch);
        }
    }

    result
}

