    words: bool,
    non_words: bool,
    escape: bool,
    with_surrogates: bool,
    repetitions: bool,
    min_repetitions: usize,
    min_substring_length: usize,
    no_start_anchor: bool,
    no_end_anchor: bool,
    no_anchors: bool,
    verbose: bool,
    colorize: bool,
    ignore_case: bool,
    capture_groups: bool,
}

impl ParsedArgs {
    fn new() -> Self {
        ParsedArgs {
            digits: false,
            non_digits: false,
            spaces: false,
            non_spaces: false,
            words: false,
            non_words: false,
            escape: false,
            with_surrogates: false,
            repetitions: false,
            min_repetitions: 1,
            min_substring_length: 1,
            no_start_anchor: false,
            no_end_anchor: false,
            no_anchors: false,
            verbose: false,
            colorize: false,
            ignore_case: false,
            capture_groups: false,
        }
    }

    fn has_char_class_conversions(&self) -> bool {
        self.digits || self.non_digits || self.spaces || self.non_spaces || self.words || self.non_words
    }
}

