fn read_from_file(path: &str) -> Vec<String> {
    if path == "-" {
        let stdin = io::stdin();
        let line = stdin.lock().lines().next();
        if let Some(Ok(line)) = line {
            read_from_file(&line)
        } else {
            Vec::new()
        }
    } else {
        match fs::read_to_string(path) {
            Ok(contents) => {
                contents
                    .lines()
                    .map(|s| s.to_string())
                    .collect()
            }
            Err(e) => {
                eprintln!("Error reading file: {}", e);
                std::process::exit(1);
            }
        }
    }
}

fn read_from_stdin() -> Vec<String> {
    let stdin = io::stdin();
    stdin
        .lock()
        .lines()
        .filter_map(|line| line.ok())
        .collect()
}

fn generate_regex(test_cases: &[String], args: &ParsedArgs) -> String {
    let mut regex = String::new();

    if args.ignore_case {
        regex.push_str("(?i)");
    }

    if !args.no_anchors && !args.no_start_anchor {
        regex.push('^');
    }

    let pattern = generate_pattern(test_cases, args);
    regex.push_str(&pattern);

    if !args.no_anchors && !args.no_end_anchor {
        regex.push('$');
    }

    if args.verbose {
        format_verbose(&regex)
    } else if args.colorize {
        colorize(&regex)
    } else {
        regex
    }
}

fn generate_pattern(test_cases: &[String], args: &ParsedArgs) -> String {
    // Deduplicate test cases
    let mut unique_cases: BTreeSet<String> = BTreeSet::new();
    for case in test_cases {
        unique_cases.insert(case.clone());
    }
    let mut cases: Vec<String> = unique_cases.into_iter().collect();

    // If character conversions are enabled, apply them first then re-deduplicate
    if args.has_char_class_conversions() {
        let converted: Vec<String> = cases.iter().map(|s| escape_pattern(s, args)).collect();
        let mut deduped: BTreeSet<String> = BTreeSet::new();
        for c in converted {
            deduped.insert(c);
        }
        cases = deduped.into_iter().collect();

        // If all are the same after conversion, return the first one
        if cases.len() == 1 {
            return cases.into_iter().next().unwrap();
        }
    }

    // If all test cases are the same
    if cases.len() == 1 {
        return escape_pattern(&cases[0], args);
    }

    // Try to extract common prefix and suffix, and handle the middle part recursively
    let prefix = find_common_prefix(&cases);
    let suffix = find_common_suffix(&cases);

    if !prefix.is_empty() || !suffix.is_empty() {
        let mut parts = Vec::new();

        if !prefix.is_empty() {
            parts.push(escape_pattern(&prefix, args));
        }

        let remaining: Vec<String> = cases
            .iter()
            .map(|s| {
                let mut s = s.as_str();
                if !prefix.is_empty() && s.starts_with(&prefix) {
                    s = &s[prefix.len()..];
                }
                if !suffix.is_empty() && s.ends_with(&suffix) {
                    s = &s[..s.len() - suffix.len()];
                }
                s.to_string()
            })
            .collect();

        if remaining.iter().all(|s| s.is_empty()) {
            // All remaining parts are empty
            let mut result = parts.join("");
            if !suffix.is_empty() {
                result.push_str(&escape_pattern(&suffix, args));
            }
            return result;
        }

        // Try character class for remaining parts if they're all single chars
        // But NOT if we have character class conversion flags enabled
        if remaining.iter().all(|s| s.len() == 1) && !args.has_char_class_conversions() {
            if let Some(char_class) = find_character_class(&remaining, args) {
                parts.push(char_class);
                if !suffix.is_empty() {
                    parts.push(escape_pattern(&suffix, args));
                }
                return parts.join("");
            }
        }

        let middle = generate_pattern(&remaining, args);
        parts.push(middle);

        if !suffix.is_empty() {
            parts.push(escape_pattern(&suffix, args));
        }

        return parts.join("");
    }

    // Try to find character class (but not if character conversions are enabled)
    if !args.has_char_class_conversions() {
        if let Some(pattern) = find_character_class(&cases, args) {
            return pattern;
        }
    }

    // Try to find optional pattern
    if let Some(pattern) = find_optional_pattern(&cases, args) {
        return pattern;
    }

    // Default: alternation
    let alternatives: Vec<String> = cases
        .iter()
        .map(|s| {
            if args.has_char_class_conversions() {
                // Already converted above
                s.clone()
            } else {
                escape_pattern(s, args)
            }
        })
        .collect();

    let group_start = if args.capture_groups { "(" } else { "(?:" };
    format!("{}{})", group_start, alternatives.join("|"))
}

fn escape_pattern(s: &str, args: &ParsedArgs) -> String {
    let mut result = String::new();

    for ch in s.chars() {
        if args.digits && ch.is_numeric() {
            result.push_str("\\d");
        } else if args.spaces && ch.is_whitespace() {
            result.push_str("\\s");
        } else if args.words && (ch.is_alphanumeric() || ch == '_') {
            result.push_str("\\w");
        } else if args.non_digits && !ch.is_numeric() {
            result.push_str("\\D");
        } else if args.non_spaces && !ch.is_whitespace() {
            result.push_str("\\S");
        } else if args.non_words && !ch.is_alphanumeric() && ch != '_' {
            result.push_str("\\W");
        } else if args.escape && !ch.is_ascii() {
            if args.with_surrogates && (ch as u32) > 0xFFFF {
                let code_point = ch as u32;
                let high = ((code_point - 0x10000) >> 10) + 0xD800;
                let low = ((code_point - 0x10000) & 0x3FF) + 0xDC00;
                result.push_str(&format!("\\u{{{:x}}}\\u{{{:x}}}", high, low));
            } else {
                result.push_str(&format!("\\u{{{:x}}}", ch as u32));
            }
        } else if needs_escaping(ch) {
            result.push('\\');
            result.push(ch);
        } else {
            result.push(ch);
        }
    }

    result
}

fn needs_escaping(ch: char) -> bool {
    matches!(ch, '.' | '*' | '+' | '?' | '(' | ')' | '[' | ']' | '{' | '}' | '|' | '\\' | '^' | '$')
}

fn find_character_class(test_cases: &[String], _args: &ParsedArgs) -> Option<String> {
    // If all test cases have the same length and are single characters
    if test_cases.iter().all(|s| s.len() == 1) && test_cases.len() > 1 {
        let mut chars: Vec<char> = test_cases.iter().flat_map(|s| s.chars()).collect();
        chars.sort();
        chars.dedup();

        // Check if we can use a range
        if chars.len() >= 2 && can_use_range(&chars) {
            return Some(format!("[{}-{}]", chars[0], chars[chars.len() - 1]));
        }

        if chars.len() > 1 {
            let char_str: String = chars.into_iter().collect();
            return Some(format!("[{}]", char_str));
        }
    }

    None
}

fn can_use_range(chars: &[char]) -> bool {
    if chars.len() < 2 {
        return false;
    }

    for i in 1..chars.len() {
        if (chars[i] as u32) != (chars[i - 1] as u32) + 1 {
            return false;
        }
    }

    true
}

fn find_optional_pattern(test_cases: &[String], args: &ParsedArgs) -> Option<String> {
    // Try to find patterns like "cat" and "cats" -> "cats?"
    if test_cases.len() == 2 {
        let s1 = &test_cases[0];
        let s2 = &test_cases[1];

        if s1.len() + 1 == s2.len() && s2.starts_with(s1) {
            let extra = &s2[s1.len()..];
            if extra.len() == 1 {
                return Some(format!("{}{}?", escape_pattern(s1, args), escape_pattern(extra, args)));
            }
        }

        if s2.len() + 1 == s1.len() && s1.starts_with(s2) {
            let extra = &s1[s2.len()..];
            if extra.len() == 1 {
                return Some(format!("{}{}?", escape_pattern(s2, args), escape_pattern(extra, args)));
            }
        }
    }

    None
}

fn find_common_prefix(test_cases: &[String]) -> String {
    if test_cases.is_empty() {
        return String::new();
    }

    let first = &test_cases[0];
    let mut prefix = String::new();

    for (i, ch) in first.chars().enumerate() {
        if test_cases.iter().all(|s| {
            s.chars().nth(i).map_or(false, |c| c == ch)
        }) {
            prefix.push(ch);
        } else {
            break;
        }
    }

    prefix
}

fn find_common_suffix(test_cases: &[String]) -> String {
    if test_cases.is_empty() {
        return String::new();
    }

    let first = &test_cases[0];
    let mut suffix = String::new();

    for (i, ch) in first.chars().rev().enumerate() {
        if test_cases.iter().all(|s| {
            s.chars().rev().nth(i).map_or(false, |c| c == ch)
        }) {
            suffix.insert(0, ch);
        } else {
            break;
        }
    }

    suffix
}

fn format_verbose(regex: &str) -> String {
    let mut result = String::from("(?x)\n");
    let mut depth: i32 = 0;
    let mut in_escape = false;

    for ch in regex.chars() {
        if in_escape {
            result.push(ch);
            in_escape = false;
        } else if ch == '\\' {
            result.push(ch);
            in_escape = true;
        } else if ch == '(' {
            if depth == 0 {
                result.push(ch);
                depth += 1;
                result.push('\n');
                for _ in 0..=depth {
                    result.push_str("  ");
                }
            } else {
                result.push(ch);
                depth += 1;
                result.push('\n');
                for _ in 0..=depth {
                    result.push_str("  ");
                }
            }
        } else if ch == ')' {
            depth -= 1;
            result.push('\n');
            for _ in 0..=depth {
                result.push_str("  ");
            }
            result.push(ch);
        } else if ch == '|' {
            result.push(ch);
            result.push('\n');
            for _ in 0..=depth {
                result.push_str("  ");
            }
        } else if ch == '^' || ch == '$' {
            if !result.ends_with('\n') && !result.ends_with(' ') {
                result.push('\n');
                for _ in 0..depth {
                    result.push_str("  ");
                }
            }
            result.push(ch);
            if ch == '^' {
                result.push('\n');
                for _ in 0..depth {
                    result.push_str("  ");
                }
            }
        } else {
            result.push(ch);
        }
    }

    result.push('\n');
    result
}

fn colorize(regex: &str) -> String {
    let mut result = String::new();
    let mut in_escape = false;
    let mut chars_iter = regex.chars().peekable();

    while let Some(ch) = chars_iter.next() {
        if in_escape {
            result.push(ch);
            in_escape = false;
        } else if ch == '\\' {
            result.push(ch);
            in_escape = true;
        } else if ch == '^' || ch == '$' {
            result.push_str("\x1b[1;33m");
            result.push(ch);
            result.push_str("\x1b[0m");
        } else if ch == '(' {
            result.push_str("\x1b[1;32m");
            result.push(ch);
            // Check for ?:
            if let Some(&next) = chars_iter.peek() {
                if next == '?' {
                    chars_iter.next();
                    result.push('?');
                    if let Some(&colon) = chars_iter.peek() {
                        if colon == ':' {
                            chars_iter.next();
                            result.push(':');
                        }
                    }
                }
            }
            result.push_str("\x1b[0m");
        } else if ch == ')' {
            result.push_str("\x1b[1;32m");
            result.push(ch);
            result.push_str("\x1b[0m");
        } else if ch == '|' {
            result.push_str("\x1b[1;31m");
            result.push(ch);
            result.push_str("\x1b[0m");
        } else {
            result.push(ch);
        }
    }

    result
}
