use std::io::{self, BufRead};
use std::fs;
use std::collections::BTreeSet;

fn main() {
    let args: Vec<String> = std::env::args().collect();

    // Parse command line arguments
    let mut parsed_args = ParsedArgs::new();
    let mut input_strings = Vec::new();
    let mut i = 1;

    while i < args.len() {
        let arg = &args[i];

        // Handle combined short flags like -di
        if arg.starts_with('-') && !arg.starts_with("--") && arg.len() > 2 {
            let chars: Vec<char> = arg.chars().collect();
            for j in 1..chars.len() {
                match chars[j] {
                    'd' => parsed_args.digits = true,
                    'D' => parsed_args.non_digits = true,
                    's' => parsed_args.spaces = true,
                    'S' => parsed_args.non_spaces = true,
                    'w' => parsed_args.words = true,
                    'W' => parsed_args.non_words = true,
                    'e' => parsed_args.escape = true,
                    'r' => parsed_args.repetitions = true,
                    'x' => parsed_args.verbose = true,
                    'c' => parsed_args.colorize = true,
                    'i' => parsed_args.ignore_case = true,
                    'g' => parsed_args.capture_groups = true,
                    'h' => {
                        print_help();
                        std::process::exit(0);
                    }
                    'v' => {
                        println!("grex 1.4.6");
                        std::process::exit(0);
                    }
                    'f' => {
                        if i + 1 >= args.len() {
                            eprintln!("Error: -f requires a filename argument");
                            std::process::exit(1);
                        }
                        i += 1;
                        let test_cases = read_from_file(&args[i]);
                        input_strings = test_cases;
                        break;
                    }
                    _ => {
                        eprintln!("Error: Unknown flag: -{}", chars[j]);
                        std::process::exit(1);
                    }
                }
            }
            i += 1;
            continue;
        }

        match arg.as_str() {
            "--help" | "-h" => {
                print_help();
                std::process::exit(0);
            }
            "--version" | "-v" => {
                println!("grex 1.4.6");
                std::process::exit(0);
            }
            "-f" | "--file" => {
                if i + 1 >= args.len() {
                    eprintln!("Error: --file requires a filename argument");
                    std::process::exit(1);
                }
                i += 1;
                let test_cases = read_from_file(&args[i]);
                input_strings = test_cases;
                i += 1;
                continue;
            }
            "-d" | "--digits" => {
                parsed_args.digits = true;
            }
            "-D" | "--non-digits" => {
                parsed_args.non_digits = true;
            }
            "-s" | "--spaces" => {
                parsed_args.spaces = true;
            }
            "-S" | "--non-spaces" => {
                parsed_args.non_spaces = true;
            }
            "-w" | "--words" => {
                parsed_args.words = true;
            }
            "-W" | "--non-words" => {
                parsed_args.non_words = true;
            }
            "-e" | "--escape" => {
                parsed_args.escape = true;
            }
            "--with-surrogates" => {
                parsed_args.with_surrogates = true;
            }
            "-r" | "--repetitions" => {
                parsed_args.repetitions = true;
            }
            "--min-repetitions" => {
                if i + 1 >= args.len() {
                    eprintln!("Error: --min-repetitions requires a number argument");
                    std::process::exit(1);
                }
                i += 1;
                parsed_args.min_repetitions = args[i].parse().unwrap_or(1);
            }
            "--min-substring-length" => {
                if i + 1 >= args.len() {
                    eprintln!("Error: --min-substring-length requires a number argument");
                    std::process::exit(1);
                }
                i += 1;
                parsed_args.min_substring_length = args[i].parse().unwrap_or(1);
            }
            "--no-start-anchor" => {
                parsed_args.no_start_anchor = true;
            }
            "--no-end-anchor" => {
                parsed_args.no_end_anchor = true;
            }
            "--no-anchors" => {
                parsed_args.no_anchors = true;
            }
            "-x" | "--verbose" => {
                parsed_args.verbose = true;
            }
            "-c" | "--colorize" => {
                parsed_args.colorize = true;
            }
            "-i" | "--ignore-case" => {
                parsed_args.ignore_case = true;
            }
            "-g" | "--capture-groups" => {
                parsed_args.capture_groups = true;
            }
            arg if arg == "-" => {
                input_strings = read_from_stdin();
                i += 1;
                continue;
            }
            arg if arg.starts_with('-') => {
                eprintln!("Error: Unknown flag: {}", arg);
                std::process::exit(1);
            }
            _ => {
                input_strings.push(arg.clone());
            }
        }
        i += 1;
    }

    if input_strings.is_empty() {
        eprintln!("Error: No test cases provided");
        std::process::exit(1);
    }

    let regex = generate_regex(&input_strings, &parsed_args);
    println!("{}", regex);
}

#[derive(Debug, Clone)]
struct ParsedArgs {
    digits: bool,
    non_digits: bool,
    spaces: bool,
    non_spaces: bool,
    words: bool,
    non_words: bool,
    escape: bool,
    with_surrogates: bool,
    repetitions: bool,
    min_repetitions: usize,
    min_substring_length: usize,
    no_start_anchor: bool,
    no_end_anchor: bool,
    no_anchors: bool,
    verbose: bool,
    colorize: bool,
    ignore_case: bool,
    capture_groups: bool,
}

impl ParsedArgs {
    fn new() -> Self {
        ParsedArgs {
            digits: false,
            non_digits: false,
            spaces: false,
            non_spaces: false,
            words: false,
            non_words: false,
            escape: false,
            with_surrogates: false,
            repetitions: false,
            min_repetitions: 1,
            min_substring_length: 1,
            no_start_anchor: false,
            no_end_anchor: false,
            no_anchors: false,
            verbose: false,
            colorize: false,
            ignore_case: false,
            capture_groups: false,
        }
    }

    fn has_char_class_conversions(&self) -> bool {
        self.digits || self.non_digits || self.spaces || self.non_spaces || self.words || self.non_words
    }
}

