    no_anchors: bool,
    verbose: bool,
    colorize: bool,
    ignore_case: bool,
    capture_groups: bool,
}

impl ParsedArgs {
    fn new() -> Self {
        ParsedArgs {
            digits: false,
            non_digits: false,
